'use strict';
// Deliberately memory-only interaction model: no credentials, backend or durable storage.
const app = document.querySelector('#app');
const escapeHTML = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const initialItems = [
  {id:1,title:'Serendipity',kind:'Слово',body:'Serendipity — счастливая случайность, неожиданная удачная находка.\n\nЭто не просто luck. В слове есть ощущение открытия: вы искали одно, а нашли нечто ценное и совсем другое.\n\nПримеры\n1. Finding that little bookshop was pure serendipity.\nНайти тот маленький книжный магазин было счастливой случайностью.\n\n2. We met through a happy serendipity.\nМы встретились благодаря счастливому стечению обстоятельств.\n\n3. Science often benefits from serendipity.\nСлучайные открытия часто помогают науке.\n\nМой контекст\nВспомнить поездку в Петербург, когда я случайно нашёл выставку по дороге на вокзал. Здесь важна не только удача, но и готовность заметить что-то новое.\n\nПроизношение\n/ˌser.ənˈdɪp.ə.ti/ — ударение на третий слог.\n\nНюанс\nСлово обычно употребляется как неисчисляемое существительное. Для упражнения достаточно самого слова и короткого перевода; весь этот конспект остаётся доступным в материале.',front:'Serendipity',back:'Счастливая случайность',exercise:true,revision:1},
  {id:2,title:'Present perfect: связь с настоящим',kind:'Грамматика',body:'Present perfect связывает прошлое с настоящим.\n\nI have lost my keys.\nЯ потерял ключи — сейчас их у меня нет.\n\nI lost my keys yesterday.\nЯ потерял ключи вчера — мы рассказываем о завершённом моменте прошлого.\n\nФорма: have / has + past participle.\n\nПопробуйте объяснить правило своими словами. Важно понять контекст, а не только назвать время.',front:'I ___ lost my keys.',back:'have',exercise:true,revision:1},
  {id:3,title:'Resilience',kind:'Слово',body:'Resilience — способность восстанавливаться после трудностей.\n\nShe showed remarkable resilience.\nОна проявила удивительную стойкость.\n\nСравнить с endurance: выносливость помогает выдержать нагрузку, resilience — восстановиться после неё.',front:'Resilience',back:'Стойкость',exercise:true,revision:1}
];
const decks=[{id:1,title:'English, в своём ритме',description:'Слова, грамматика и примеры из моей жизни.',items:initialItems,captures:[{id:1,text:'Разобраться с difference between affect and effect',created:new Date().toISOString()}],completed:false}];
let deck=decks[0], nextItem=4, nextCapture=2, session=null, draft=null;
const announce = text => { document.querySelector('#announcement').textContent=text; };
const link=(href,text,primary=false)=>`<a class="button${primary?' primary':''}" href="${href}">${text}</a>`;
function header(landing=false){return `<header class="site-header wrap"><a class="brand" href="#/" aria-label="Mnema — главная"><span class="star" aria-hidden="true">✺</span>MNEMA</a><nav aria-label="Основная навигация">${landing?'<a href="#materials">Материалы</a><a href="#exercises">Упражнения</a><a href="#rhythm">Как учиться</a>':'<a href="#/decks">Мои колоды</a><a href="#/">О Mnema</a>'}</nav>${link('#/decks',landing?'Попробовать →':'Открыть колоды →')}</header>`;}
function footer(){return '<footer class="site-footer wrap"><span>MNEMA · ДЛЯ ТЕХ, КТО ЛЮБИТ УЧИТЬСЯ</span><span>Интерактивный макет · сентябрь 2026</span><a href="#/">К началу ↑</a></footer>';}
function shell(content,landing=false){app.innerHTML=header(landing)+(landing?'':'<div class="demo-banner"><div class="wrap">Демо без регистрации. Данные живут только до перезагрузки страницы; сервер не подключён.</div></div>')+`<main id="main" tabindex="-1" class="${landing?'wrap':'wrap workspace'}">${content}</main>`+footer();document.querySelector('main').focus({preventScroll:true});}
function landing(){shell(`<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow">Для любопытства, которое остаётся с вами</p><h1 id="hero-title">Учиться.<br>Понимать.<br>Помнить.</h1><p class="hero-description">Ваши материалы и упражнения — в одном месте. Собирайте важное, учитесь по-своему и возвращайтесь к знаниям вовремя.</p><div class="hero-actions">${link('#/decks','Начать с моей колоды →',true)}<a href="#materials">Как это устроено</a></div><div class="constellation" aria-hidden="true"></div></div><div class="art"><img src="assets/mnemosyne-engraving.png" alt="Мнемозина в античной гравюре цвета индиго" width="1024" height="1536" fetchpriority="high"><span class="art-label">MNEMOSYNE<br>БОГИНЯ ПАМЯТИ</span><span class="art-caption" aria-hidden="true">ΜΝΗΜΟΣΥΝΗ</span><a class="note hero-note" href="#exercises"><span class="eyebrow">Вы выбираете способ</span><h2>Ваши знания.<br>Ваши упражнения.<br>Ваш ритм.</h2><span class="arrow">УЧИТЬСЯ ПО-СВОЕМУ →</span></a><a class="note small-note" href="#rhythm"><span class="star" aria-hidden="true">✧</span> Память — это больше,<br>чем хранение.<br>Это понимание. →</a></div></section><div class="feature-strip"><a href="#materials"><span class="star" aria-hidden="true">☼</span><span><strong>Всё важное рядом</strong>Слова, конспекты и примеры в ваших колодах.</span></a><a href="#exercises"><span class="star" aria-hidden="true">◎</span><span><strong>Упражнения под вас</strong>Один материал. Несколько способов понять.</span></a><a href="#rhythm"><span class="star" aria-hidden="true">✳</span><span><strong>Помнить надолго</strong>Повторяйте вовремя. Практикуйтесь когда хочется.</span></a></div><section class="landing-section" id="materials"><div><p class="eyebrow">01 / Собирайте</p><h2>Мысль — короткая.<br>Знание — глубокое.</h2><p>Сохраните находку «На потом», пока идёт урок. Позже добавьте примеры, пояснения и собственные связи. В одной колоде могут жить слова, грамматика и большой конспект.</p>${link('#/deck/1','Открыть пример колоды →')}</div><div class="specimen"><span class="eyebrow">Из колоды English, в своём ритме</span><blockquote>Serendipity<br>Счастливая случайность.</blockquote><p>Finding that little bookshop was pure serendipity.</p><div class="ruled-row"><span>Мой контекст</span><span class="mini-tag">заметка</span></div><p>Тот книжный магазин, на который я наткнулся по дороге домой.</p></div></section><section class="landing-section" id="exercises"><div class="specimen"><span class="eyebrow">Один материал → разные упражнения</span><div class="ruled-row"><span>Вспомнить перевод</span><span>↔</span></div><div class="ruled-row"><span>Соединить пары</span><span>◎</span></div><div class="ruled-row"><span>Заполнить пропуск</span><span>＿</span></div><p class="help">В упражнение попадает выбранный фрагмент. Полный материал всегда остаётся рядом.</p></div><div><p class="eyebrow">02 / Разбирайтесь</p><h2>Не всё знание<br>помещается на карточке.</h2><p>Сам материал может быть большим. Для упражнения выберите самое нужное: слово и перевод, вопрос и объяснение, короткий пример. Содержание и способ тренировки выбираете вы.</p>${link('#/item/1','Попробовать редактор →')}</div></section><section class="landing-section" id="rhythm"><div><p class="eyebrow">03 / Возвращайтесь</p><h2>В своём темпе.<br>С местом для повторения.</h2><p>Занимайтесь внутри выбранной колоды. После занятия можно повторить ту же сессию или потренировать всю колоду — столько раз, сколько нужно.</p><p>Дополнительная практика не меняет расписание повторений. А если хочется начать материал заново, вы решаете это сами.</p>${link('#/study/scheduled','Попробовать занятие →')}</div><div class="specimen"><span class="eyebrow">Когда занятие закончено</span><h3>Можно остаться ещё.</h3><div class="ruled-row"><span>Повторить сегодняшнее</span><span>↻</span></div><div class="ruled-row"><span>Потренировать всю колоду</span><span>✧</span></div><div class="ruled-row"><span>Вернуться к материалам</span><span>→</span></div></div></section><section class="final-cta"><span class="star" aria-hidden="true">✺</span><h2>Оставьте место любопытству.</h2><p>Начните с одной колоды. Наполните её тем, что важно вам.</p>${link('#/new','Создать свою колоду →',true)}</section>`,true);}
function crumbs(last=''){return `<div class="breadcrumbs"><a href="#/decks">Мои колоды</a>${last?`<span>/</span><a href="#/deck/${deck.id}">${escapeHTML(deck.title)}</a><span>/ ${escapeHTML(last)}</span>`:''}</div>`;}
function decksPage(){shell(`<div class="page-heading"><div><p class="eyebrow">Место для вашего любопытства</p><h1>Мои колоды</h1><p>У каждой темы — свой материал и свой ритм обучения.</p></div>${link('#/new','+ Создать колоду',true)}</div><div class="deck-list">${decks.map((d,i)=>`<article class="deck-row"><span class="deck-number">${String(i+1).padStart(2,'0')}</span><div><h2><a href="#/deck/${d.id}">${escapeHTML(d.title)}</a></h2><p>${escapeHTML(d.description||'Здесь начнётся ваша новая тема.')}<br>${d.items.length} материала · ${d.captures.length} на потом · ${d.completed?'сегодняшнее занятие завершено':'можно начать занятие'}</p></div>${link(`#/deck/${d.id}`,'Открыть →')}</article>`).join('')}</div><p class="help spaced">Пока здесь только ваши колоды. Общий каталог появится на следующем этапе продукта.</p>`);}
function newDeck(){shell(`${crumbs()}<h1>С чего начнём?</h1><p>Язык, экзамен или идея, в которую хочется погрузиться. Вы задаёте границы колоды.</p><form id="new-deck" class="form-sheet"><div class="field"><label for="title">Название колоды</label><input id="title" name="title" required maxlength="120" placeholder="Например, история искусства"></div><div class="field"><label for="description">О чём эта колода</label><textarea id="description" name="description" maxlength="1000" placeholder="Необязательно. Пара слов для себя."></textarea></div><div class="actions"><button class="primary" type="submit">Создать колоду →</button><a href="#/decks">Отмена</a></div></form>`);document.querySelector('#new-deck').addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget);const title=String(f.get('title')).trim();if(!title){document.querySelector('#title').setCustomValidity('Введите название, а не только пробелы.');document.querySelector('#title').reportValidity();return;}deck={id:decks.length+1,title,description:String(f.get('description')).trim(),items:[],captures:[],completed:false};decks.push(deck);location.hash=`/deck/${deck.id}`;});document.querySelector('#title').addEventListener('input',e=>e.target.setCustomValidity(''));}
function deckPage(){shell(`${crumbs()}<div class="page-heading"><div><p class="eyebrow">Моя колода · только для меня</p><h1>${escapeHTML(deck.title)}</h1><p>${escapeHTML(deck.description)}</p></div><div class="actions">${link('#/item/new','+ Материал')}${deck.items.some(i=>i.exercise)?link(deck.completed?'#/complete':'#/study/scheduled',deck.completed?'Заниматься ещё →':'Начать занятие →',true):''}</div></div><div class="deck-grid"><section><div class="section-title"><h2>Материалы</h2><span class="mini-tag">${deck.items.length} в колоде</span></div>${deck.items.length?deck.items.map(i=>`<article class="material-row"><span class="eyebrow">${escapeHTML(i.kind)} · редакция ${i.revision}</span><h3><a href="#/item/${i.id}">${escapeHTML(i.title)}</a></h3><p>${escapeHTML(i.body.slice(0,115))}…</p><span class="mini-tag">${i.exercise?'Есть упражнение':'Без упражнения · не участвует в занятии'}</span></article>`).join(''):'<div class="empty"><h3>Пока чистый лист.</h3><p>Добавьте первый материал или запишите мысль «На потом».</p>'+link('#/item/new','Добавить материал →')+'</div>'}<div class="notice">${deck.completed?'Сегодняшнее занятие завершено. Дополнительная практика не меняет расписание.':'Учимся в пределах этой колоды. Степень освоения не вычисляется в макете.'}</div></section><aside class="side-note"><span class="eyebrow">Мысли, к которым вернётесь</span><h2>На потом <span aria-hidden="true">✧</span></h2><p>Короткая запись сейчас, полноценный материал — когда будет время. Эти записи не участвуют в обучении.</p><form id="capture-form"><label for="capture-text">Что хочется запомнить?</label><textarea id="capture-text" required maxlength="2000" placeholder="Мысль, слово или вопрос…"></textarea><button class="wide spaced" type="submit">Оставить на потом +</button></form><div id="captures">${deck.captures.map(c=>`<article class="capture"><p>${escapeHTML(c.text)}</p><time datetime="${c.created}">${new Date(c.created).toLocaleDateString('ru-RU')}</time><div><button class="text" data-convert="${c.id}">Разобрать →</button></div></article>`).join('')||'<p class="help spaced">Здесь пока нет записей.</p>'}</div></aside></div>`);document.querySelector('#capture-form').addEventListener('submit',e=>{e.preventDefault();const text=document.querySelector('#capture-text').value.trim();if(!text)return;deck.captures.unshift({id:nextCapture++,text,created:new Date().toISOString()});deckPage();announce('Запись добавлена на потом в этой демосессии.');});document.querySelectorAll('[data-convert]').forEach(b=>b.addEventListener('click',()=>{const c=deck.captures.find(c=>c.id===Number(b.dataset.convert));draft={id:'new',deckId:deck.id,title:c.text.slice(0,80),body:c.text,front:'',back:'',exercise:false,captureId:c.id};location.hash='/item/new';}));}
function itemPage(id){const existing=deck.items.find(i=>i.id===Number(id));if(id!=='new'&&!existing){shell('<h1>Материал не найден</h1><p>Эта ссылка отсутствует в демонстрационной колоде.</p>'+link(`#/deck/${deck.id}`,'Вернуться к колоде'));return;}if(!draft||String(draft.id)!==String(id)||(id==='new'&&draft.deckId!==deck.id))draft=existing?{...existing,deckId:deck.id}:{id:'new',deckId:deck.id,title:'',body:'',front:'',back:'',exercise:false};shell(`${crumbs(existing?'Материал':'Новый материал')}<div class="page-heading"><div><p class="eyebrow">Содержание и способ обучения</p><h1>${existing?escapeHTML(existing.title):'Новый материал'}</h1></div><a href="#/deck/${deck.id}">← К колоде</a></div><form id="editor"><div class="editor-grid"><section><div class="field"><label for="item-title">Название материала</label><input id="item-title" name="title" required maxlength="160" value="${escapeHTML(draft.title)}"></div><div class="field"><label for="item-body">Материал целиком</label><textarea id="item-body" class="document" name="body" required maxlength="50000">${escapeHTML(draft.body)}</textarea><p class="help">Материал может быть длинным. Короткие представления для упражнений задаются отдельно.</p></div><details><summary>Предпросмотр материала</summary><div id="preview" class="preview">${escapeHTML(draft.body)}</div></details><div class="save-bar"><button type="submit" class="primary">Сохранить материал →</button><span id="save-status" class="status" role="status">${existing?'Сохранённая редакция '+existing.revision:'Ещё не сохранён'}</span></div><p class="help">Редактор держит правки в памяти демо. После перезагрузки они исчезнут. В продукте восстановление черновика будет серверным.</p></section><aside class="side-note"><p class="eyebrow">Представление для упражнения</p><h2>Как вспоминать?</h2><p>Выберите обе стороны. Сохранение текста материала само по себе не создаёт упражнение.</p><div class="field"><label for="exercise-enabled">Упражнение «Вспомнить»</label><select id="exercise-enabled" name="exercise"><option value="no" ${!draft.exercise?'selected':''}>Не добавлено</option><option value="yes" ${draft.exercise?'selected':''}>Добавить к материалу</option></select></div><div class="field"><label for="front">Вопрос / лицевая сторона</label><textarea id="front" name="front" maxlength="160" placeholder="Короткое слово или вопрос">${escapeHTML(draft.front)}</textarea></div><div class="field"><label for="back">Ответ / обратная сторона</label><textarea id="back" name="back" maxlength="240" placeholder="Перевод или объяснение">${escapeHTML(draft.back)}</textarea></div><p class="help">В макете: до 160 / 240 символов. Ограничение конкретного упражнения, не всего материала.</p><p id="exercise-error" class="error" role="alert"></p><div class="exercise-card"><h3>Соединить пары</h3><p>Использует короткие подписи двух слов этой колоды. Грамматика остаётся отдельным материалом.</p>${link('#/study/practice','Попробовать упражнения →')}</div>${existing?'<details><summary>Начать обучение материала заново</summary><p>Это отдельное действие. Обычное изменение ответа сохраняет состояние обучения.</p><button type="button" id="reset-learning">Учить заново</button><p id="reset-status" class="help" role="status"></p></details>':''}</aside></div></form>`);const form=document.querySelector('#editor');form.addEventListener('input',()=>{const f=new FormData(form);Object.assign(draft,{title:String(f.get('title')),body:String(f.get('body')),front:String(f.get('front')),back:String(f.get('back')),exercise:f.get('exercise')==='yes'});document.querySelector('#preview').textContent=draft.body;document.querySelector('#save-status').textContent='Есть несохранённые правки · обучение использует сохранённую редакцию';});form.addEventListener('submit',e=>{e.preventDefault();if(!draft.title.trim()||!draft.body.trim()){document.querySelector('#exercise-error').textContent='Добавьте название и содержание материала.';return;}if(draft.exercise&&(!draft.front.trim()||!draft.back.trim())){document.querySelector('#exercise-error').textContent='Для упражнения заполните обе стороны.';return;}const savingDraft={...draft};const savingDeck=deck;const routeAtSave=location.hash;const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Сохраняем в демо…';document.querySelector('#save-status').textContent='Демонстрация состояния сохранения';setTimeout(()=>{const saved={...savingDraft,id:existing?existing.id:nextItem++,kind:existing?.kind||'Материал',revision:(existing?.revision||0)+1};delete saved.captureId;delete saved.deckId;if(existing)Object.assign(existing,saved);else savingDeck.items.push(saved);if(savingDraft.captureId)savingDeck.captures=savingDeck.captures.filter(c=>c.id!==savingDraft.captureId);if(location.hash===routeAtSave){draft=null;location.hash=`/item/${saved.id}`;if(existing)itemPage(saved.id);}announce('Материал сохранён в памяти демо.');},350);});document.querySelector('#reset-learning')?.addEventListener('click',()=>{document.querySelector('#reset-status').textContent='В продукте здесь будет подтверждение сброса именно этого материала. В макете алгоритм обучения не подключён.';});}
function shuffle(values,seed){const copy=[...values];for(let i=copy.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[copy[i],copy[j]]=[copy[j],copy[i]];}return copy;}
function startSession(mode){const eligible=deck.items.filter(i=>i.exercise);if(!eligible.length){shell('<h1>Пока нечего повторять</h1><p>Добавьте упражнение к сохранённому материалу.</p>'+link(`#/deck/${deck.id}`,'К материалам'));return;}if(mode==='scheduled'&&deck.completed){complete();return;}const seed=mode==='replay'?(deck.lastSession?.seed||17):Math.floor(Math.random()*100000);const items=mode==='replay'&&deck.lastSession?structuredClone(deck.lastSession.items):shuffle(eligible,seed);session={mode,seed,items:structuredClone(items),step:0,revealed:false,matched:[],selected:null,feedback:''};study();}
function study(){const {mode,items:allItems,step}=session;const words=allItems.filter(i=>i.kind==='Слово');const items=step===1&&words.length>=2?words:allItems;const types=words.length>=2?['flash','match','typed']:['flash','typed'];if(step>=types.length){if(mode==='scheduled'){deck.completed=true;deck.lastSession={seed:session.seed,items:structuredClone(items)};}complete();return;}const type=types[step], item=items[0];shell(`<div class="study-shell"><div class="study-header"><div><a href="#/deck/${deck.id}">${escapeHTML(deck.title)}</a><p class="study-mode">${mode==='scheduled'?'ЗАНЯТИЕ ПО РАСПИСАНИЮ':mode==='replay'?'ПОВТОР СЕГОДНЯШНЕГО ЗАНЯТИЯ':'СВОБОДНАЯ ПРАКТИКА'} · ${step+1} / ${types.length}</p></div><a href="#/deck/${deck.id}">Завершить</a></div>${mode!=='scheduled'?'<p class="notice">Дополнительная практика. Расписание и основной прогресс не меняются.</p>':'<p class="help">Демонстрация занятия: алгоритм повторений и расчёт освоения не подключены.</p>'}<section class="study-paper">${type==='flash'?`<p class="eyebrow">Вспомнить · выбранные стороны материала</p><h1 class="word">${escapeHTML(item.front)}</h1><p>Вспомните ответ. Затем откройте обратную сторону.</p>${session.revealed?`<div class="answer"><h2>${escapeHTML(item.back)}</h2><p class="help">Оцените свой ответ честно — это помогает подобрать повторение.</p></div>`:'<button id="reveal" class="primary">Показать ответ</button>'}`:type==='match'?`<p class="eyebrow">Соединить пары</p><h1>Найдите друг друга.</h1><p>Выберите подпись слева, затем соответствие справа.</p><div class="matching"><div class="match-column">${items.slice(0,2).map(i=>`<button data-left="${i.id}" aria-pressed="${session.selected===i.id}" ${session.matched.includes(i.id)?'disabled class="matched"':''}>${escapeHTML(i.front)}${session.matched.includes(i.id)?' ✓':''}</button>`).join('')}</div><div class="match-column">${shuffle(items.slice(0,2),session.seed+2).map(i=>`<button data-right="${i.id}" ${session.matched.includes(i.id)?'disabled class="matched"':''}>${escapeHTML(i.back)}${session.matched.includes(i.id)?' ✓':''}</button>`).join('')}</div></div><p id="match-feedback" role="status" class="${session.feedback.includes('попробуйте')?'error':'success'}">${escapeHTML(session.feedback)}</p>`:`<p class="eyebrow">Короткий ответ</p><h1>Проверьте себя.</h1><blockquote>${escapeHTML(item.front)}</blockquote><form id="typed-form"><label for="typed">Ваш ответ</label><input id="typed" autocomplete="off" required maxlength="240"><p id="typed-feedback" role="status"></p><button class="primary spaced" type="submit">Проверить ответ</button></form>`}</section><div class="study-bottom"><span class="seed">${mode==='replay'?'Снимок сегодняшнего занятия':'Порядок демо'} · ${session.seed}</span><div class="actions">${type==='flash'&&session.revealed?'<button data-next>Пока не вспомнил</button><button data-next class="primary">Вспомнил →</button>':type==='match'&&session.matched.length===2?'<button data-next class="primary">Продолжить →</button>':'<button id="skip-exercise" class="text">Пропустить →</button>'}</div></div><details class="spaced"><summary>Посмотреть материал</summary><div class="preview">${escapeHTML(item.body)}</div></details></div>`);document.querySelector('#reveal')?.addEventListener('click',()=>{session.revealed=true;study();document.querySelector('[data-next]').focus();});document.querySelectorAll('[data-next],#skip-exercise').forEach(b=>b.addEventListener('click',next));document.querySelectorAll('[data-left]').forEach(b=>b.addEventListener('click',()=>{session.selected=Number(b.dataset.left);session.feedback='Теперь выберите соответствие справа.';study();document.querySelector('[data-right]:not(:disabled)')?.focus();}));document.querySelectorAll('[data-right]').forEach(b=>b.addEventListener('click',()=>{const id=Number(b.dataset.right);if(!session.selected)session.feedback='Сначала выберите подпись слева.';else if(session.selected===id){session.matched.push(id);session.selected=null;session.feedback=session.matched.length===2?'Все пары найдены.':'Пара найдена.';}else session.feedback='Пока не совпало — попробуйте ещё раз.';study();(document.querySelector('[data-left]:not(:disabled)')||document.querySelector('[data-next]'))?.focus();}));document.querySelector('#typed-form')?.addEventListener('submit',e=>{e.preventDefault();const actual=document.querySelector('#typed').value.trim().toLocaleLowerCase('ru');const correct=actual===item.back.trim().toLocaleLowerCase('ru');document.querySelector('#typed-feedback').textContent=correct?'Верно.':`В сохранённом упражнении: ${item.back}.`;document.querySelector('#typed-feedback').className=correct?'success':'error';const button=e.currentTarget.querySelector('button');button.type='button';button.textContent='Продолжить →';button.onclick=next;});}
function next(){session.step++;session.revealed=false;session.selected=null;session.matched=[];session.feedback='';study();}
function complete(){shell(`<div class="study-shell"><p class="eyebrow">${deck.completed?'Сегодняшнее занятие завершено':'Практика завершена'}</p><h1>Хорошее место,<br>чтобы остановиться.<br>Или продолжить.</h1><p>${session?.mode&&session.mode!=='scheduled'?'Дополнительная практика закончена. Основной прогресс и расписание остались прежними.':'Можно вернуться к конспектам, ещё раз пройти сегодняшнее занятие или потренироваться свободно.'}</p><div class="mode-options"><a href="#/deck/${deck.id}"><strong>Вернуться к материалам →</strong><span>Читать, дополнять и выбирать упражнения.</span></a>${deck.lastSession?'<a href="#/study/replay"><strong>Повторить сегодняшнее ↻</strong><span>Тот же снимок материалов и упражнений. Без изменения расписания и основного прогресса.</span></a>':''}<a href="#/study/practice"><strong>Потренировать колоду ✧</strong><span>Новый порядок сохранённых упражнений. Без изменения расписания. В макете — короткая последовательность из 2–3 заданий.</span></a></div></div>`);}
function route(){const hash=location.hash.slice(1)||'/';if(!hash.startsWith('/'))return;const parts=hash.split('/').filter(Boolean);if(parts[0]==='deck'){deck=decks.find(d=>d.id===Number(parts[1]))||decks[0];deckPage();}else if(parts[0]==='decks')decksPage();else if(parts[0]==='new')newDeck();else if(parts[0]==='item'){const found=decks.find(d=>d.items.some(i=>i.id===Number(parts[1])));if(found)deck=found;itemPage(parts[1]||'new');}else if(parts[0]==='study')startSession(['scheduled','replay','practice'].includes(parts[1])?parts[1]:'scheduled');else if(parts[0]==='complete')complete();else landing();window.scrollTo(0,0);}
window.addEventListener('hashchange',route);route();
